package com.example.starter.fermentation.domain;

import java.math.BigDecimal;

/**
 * 工艺曲线分段设定。
 *
 * @param id              分段 ID
 * @param curveId         所属曲线版本 ID
 * @param phase           阶段
 * @param seq             阶段内分段序号，从 1 开始
 * @param setpointCelsius 温度设定值，单位摄氏度，允许负值
 * @param durationHours   持续时长，单位小时
 */
public record CurveSegment(
        long id,
        long curveId,
        CurvePhase phase,
        int seq,
        BigDecimal setpointCelsius,
        int durationHours) {
}

package com.example.starter.fermentation.domain;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 双乙酰检测记录。连续两次检测均不超过 0.10 mg/L（恰 0.10 合格）且间隔不少于 12 小时（恰 12 小时合法）方可降温。
 *
 * @param id             记录 ID
 * @param batchId        所属批次 ID
 * @param testedAt       检测时间
 * @param valueMgPerLiter 双乙酰含量，单位 mg/L
 * @param late           是否迟到数据（批次已转出后到达）
 */
public record DiacetylTest(
        long id,
        long batchId,
        LocalDateTime testedAt,
        BigDecimal valueMgPerLiter,
        boolean late) {
}

