/**
 * 发酵批次测试基类：使用独立 H2 内存库（test_demo），每个用例前清理业务数据，
 * 提供贯穿“满罐→主酵→降温→后熟→判定→转出”的合成数据驱动助手。
 */
@SpringBootTest
@AutoConfigureMockMvc
public abstract class BaseFermentationTest {

    /** 合成基准时间：满罐时刻。 */
    static final LocalDateTime T0 = LocalDateTime.of(2026, 9, 26, 8, 0);

    @Autowired
    MockMvc mockMvc;

    @Autowired
